import Application, { Item } from "../models/Application";
import UserService from "../services/UserService";
export default class LoginController {
    constructor(form, logoutButton) {
        this.form = form;
        this.logoutButton = logoutButton;
        this.application = Application.getInstance();
        this.form = form;
        this.form.onsubmit = (event) => this.onSubmit(event);
        if (logoutButton)
            logoutButton.onclick = (event) => this.onLogout(event);
    }
    async onSubmit(event) {
        event.preventDefault();
        const formData = new FormData(this.form);
        const email = formData.get("email");
        const password = formData.get("password");
        const { token, user } = await UserService.login(email, password);
        this.application.set(Item.CurrentUser, user);
        this.application.set(Item.AuthToken, token);
        if (window.location.pathname === "/login") {
            window.location.href = "/";
        }
        else {
            window.location.reload();
        }
    }
    onLogout(event) {
        event.preventDefault();
        console.log(this.application.get(Item.CurrentUser));
        // this.model.set(Item.CurrentUser, null);
        // this.model.set(Item.AuthToken, null);
        // window.location.reload();
    }
}
